package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.worklog.*;
import cn.mop.domain.worklog.WorklogRepository.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class OwnWorklogControllerTest {
    final String actor="7e000000-0000-4000-8000-000000000001",tenant="7e000000-0000-4000-8000-000000000002",ticket="7e000000-0000-4000-8000-000000000003",id="7e000000-0000-4000-8000-000000000004";
    PlatformRepository platform;WorklogRepository repository;OwnWorklogController controller;final Instant time=Instant.parse("2026-10-04T00:00:00Z");
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(WorklogRepository.class);controller=new OwnWorklogController(platform,repository);when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"msp",7,true)));when(repository.listOwnAcrossTickets(any(),any(),anyInt(),any(),any())).thenReturn(List.of());}
    Access access(){return new Access(actor,tenant,7,"own-worklog-read");}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/v1/my/worklogs");r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);r.setAttribute("mop.trace_id","own-worklog-read");return r;}
    Entry entry(String owner){return new Entry(id,tenant,ticket,owner,1,time,time,new ManualWorklog(ManualWorklog.Kind.REMOTE,time,time.plusSeconds(49*3600),null));}
    Map<?,?> data(Object v){return (Map<?,?>)((Map<?,?>)v).get("data");}
    @Test void defaultReadDoesNotInventPeriodAggregatesOrFinancialValues(){var d=data(controller.list(request()));assertEquals(tenant,d.get("tenant_id"));assertEquals(actor,d.get("owner_id"));assertNull(d.get("aggregates"));assertEquals(false,d.get("snapshot_frozen"));assertEquals("CONFIG_PENDING",d.get("financial_status"));var f=(Map<?,?>)d.get("filters");assertTrue(f.values().stream().allMatch(Objects::isNull));verify(repository).listOwnAcrossTickets(access(),new OwnWorklogQuery(null,null,null,null),16,null,null);}
    @Test void explicitFiltersAreNormalizedWithoutClippingReturnedInterval(){var r=request();r.addParameter("ticket_id",ticket);r.addParameter("kind","REMOTE");r.addParameter("started_from","2026-10-04T08:00:00+08:00");r.addParameter("started_before","2026-10-04T08:00:01+08:00");when(repository.listOwnAcrossTickets(any(),any(),anyInt(),any(),any())).thenReturn(List.of(entry(actor)));var d=data(controller.list(r));var one=(Map<?,?>)((List<?>)d.get("items")).get(0);assertEquals(49*3600000L,one.get("elapsed_millis"));assertNull(one.get("labor_cost"));verify(repository).listOwnAcrossTickets(access(),new OwnWorklogQuery(UUID.fromString(ticket),ManualWorklog.Kind.REMOTE,time,time.plusSeconds(1)),16,null,null);}
    @Test void lookaheadReturnsExactPageAndPairedCursor(){when(repository.listOwnAcrossTickets(any(),any(),anyInt(),any(),any())).thenReturn(Collections.nCopies(16,entry(actor)));var d=data(controller.list(request()));assertEquals(15,((List<?>)d.get("items")).size());assertEquals(true,d.get("has_more"));assertEquals(time,d.get("next_before_created_at"));assertEquals(id,d.get("next_before_id"));assertEquals(20,d.get("page_size_limit"));}
    @Test void unknownOwnerTenantAggregateAndDuplicateQueriesAreRejected(){for(String k:List.of("owner_id","tenant_id","aggregate","month","team")){var r=request();r.addParameter(k,"anything");assertEquals(400,assertThrows(DomainException.class,()->controller.list(r)).status);}var r=request();r.addParameter("kind","REMOTE","ONSITE");assertThrows(DomainException.class,()->controller.list(r));verifyNoInteractions(repository);}
    @Test void pageAndCursorBoundsRequireExactSupportedValues(){for(String n:List.of("0","21","100","15.0","015")){var r=request();r.addParameter("page_size",n);assertThrows(DomainException.class,()->controller.list(r));}for(String k:List.of("before_id","before_created_at","started_from","started_before")){var r=request();r.addParameter(k,k.endsWith("id")?id:time.toString());assertThrows(DomainException.class,()->controller.list(r));}}
    @Test void malformedKindTicketTimeAndReversedWindowAreRejected(){for(String[] pair:new String[][]{{"kind","remote"},{"kind","ALL"},{"ticket_id","bad"},{"page_size"," "}}){var r=request();r.addParameter(pair[0],pair[1]);assertThrows(DomainException.class,()->controller.list(r));}var r=request();r.addParameter("started_from",time.toString());r.addParameter("started_before",time.toString());assertThrows(DomainException.class,()->controller.list(r));r.setParameter("started_before","2026-10-04T00:00:00.000001Z");assertThrows(DomainException.class,()->controller.list(r));}
    @Test void sessionAndCurrentRoleGatePrecedeFilterOrRepository(){for(String role:List.of("padmin","viewer","tadmin","unknown")){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,role,7,true)));var r=request();r.addParameter("tenant_id","bad");assertEquals(403,assertThrows(DomainException.class,()->controller.list(r)).status);}assertEquals(401,assertThrows(DomainException.class,()->controller.list(new MockHttpServletRequest())).status);verifyNoInteractions(repository);}
    @Test void inactiveMemberCannotReadEvenWithExistingSession(){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"msp",8,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.list(request())).status);verifyNoInteractions(repository);}
    @Test void missingOrForeignRepositoryProjectionFailsClosed(){when(repository.listOwnAcrossTickets(any(),any(),anyInt(),any(),any())).thenReturn(null);assertEquals(503,assertThrows(DomainException.class,()->controller.list(request())).status);when(repository.listOwnAcrossTickets(any(),any(),anyInt(),any(),any())).thenReturn(List.of(entry(id)));assertEquals(503,assertThrows(DomainException.class,()->controller.list(request())).status);}
    @Test void oversizedRawQueryIsRejectedBeforeRepository(){var r=request();r.setQueryString("x="+"a".repeat(2048));assertEquals(400,assertThrows(DomainException.class,()->controller.list(r)).status);verifyNoInteractions(repository);}
}
